export interface ProjectReference {
    /** Path is a normalized path on disk. */
    path: string;
    /** OriginalPath is the path as it was originally written. */
    originalPath: string;
    /** Circular indicates that this reference is intended to form a circularity. */
    circular: boolean;
}

